use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. A request outside
/// this set would trap at the boundary and fail the whole tick, so such URLs
/// are recorded as failures without ever being asked for.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, conservatively. Anything ambiguous
/// (userinfo, backslashes, whitespace, control characters) yields `None`.
fn host_of(url: &str) -> Option<String> {
    let rest = if url.len() >= 8 && url[..8].eq_ignore_ascii_case("https://") {
        &url[8..]
    } else if url.len() >= 7 && url[..7].eq_ignore_ascii_case("http://") {
        &url[7..]
    } else {
        return None;
    };

    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    if authority.is_empty()
        || authority
            .chars()
            .any(|c| c == '@' || c == '\\' || c.is_whitespace() || c.is_control())
    {
        return None;
    }

    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if !port.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            &authority[..i]
        }
        None => authority,
    };

    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|h| *h == host),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received, one URL per line.
        let recorded = subscriptions.urls.join("\n");
        state_rw::put("last-input", &recorded);

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("host not in this node's allowlist; not fetched"),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

The world imports `aap:caps/state-rw@0.1.0` alongside `aap:caps/http-client@0.1.0`, and each call stores the subscription URLs, newline-joined, under `last-input` before fetching; the returned `feed-batch` is unaffected. Until the graph definition carries the grant, a host that binds only the declared `with` clause will refuse to instantiate this component.

